// Isolation test (OS-12) — construct ScopeGate with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { noSubject, type RecordHeight } from "../src/kernel/index.js";
import { ScopeGate, type DrawCharges, type ScopeReads } from "../src/spend/index.js";
import { c0, c1, scopeWorld, u } from "./support/spend-parts.js";

/** A scope of ceiling one for (u, c0), read by its own height; and a height to read at. */
function parts() {
  const w = scopeWorld();
  const s = w.authorize(c0, 1);
  const scopes: ScopeReads = { governing: () => s, scopeAt: () => s };
  const charges: DrawCharges = { drawsUnder: () => [] };
  return { s, h: w.record.noise(), scopes, charges };
}
const none: ScopeReads = { governing: () => noSubject(), scopeAt: () => noSubject() };
const oneDraw = (at: RecordHeight): DrawCharges => ({ drawsUnder: () => [at] });

describe("ScopeGate in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { scopes, charges } = parts();
    expect(() => new ScopeGate({ charges } as never)).toThrow();
    expect(() => new ScopeGate({ scopes } as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { scopes, charges } = parts();
    expect(() => new ScopeGate({ scopes: {} as never, charges })).toThrow();
    expect(() => new ScopeGate({ scopes: { governing: scopes.governing } as never, charges })).toThrow();
    expect(() => new ScopeGate({ scopes, charges: {} as never })).toThrow();
  });

  it("remaining answers differently when scopes differs", () => {
    const { h, scopes, charges } = parts();
    expect(new ScopeGate({ scopes, charges }).remaining(u, c0, h)).not.toEqual(new ScopeGate({ scopes: none, charges }).remaining(u, c0, h));
  });

  it("remaining answers differently when charges differs", () => {
    const { h, scopes, charges } = parts();
    expect(new ScopeGate({ scopes, charges }).remaining(u, c0, h)).not.toEqual(new ScopeGate({ scopes, charges: oneDraw(h) }).remaining(u, c0, h));
  });

  it("admitsDraw answers differently when scopes differs", () => {
    const { s, h, scopes, charges } = parts();
    expect(new ScopeGate({ scopes, charges }).admitsDraw(u, s.at, h)).not.toEqual(new ScopeGate({ scopes: none, charges }).admitsDraw(u, s.at, h));
  });

  it("admitsDraw answers differently when charges differs", () => {
    const { s, h, scopes, charges } = parts();
    expect(new ScopeGate({ scopes, charges }).admitsDraw(u, s.at, h)).not.toEqual(new ScopeGate({ scopes, charges: oneDraw(h) }).admitsDraw(u, s.at, h));
  });

  it("admitsCandidate answers differently when scopes differs (and reads no charges)", () => {
    const { s, h, scopes, charges } = parts();
    expect(new ScopeGate({ scopes, charges }).admitsCandidate(u, c0, s.at, h)).not.toEqual(new ScopeGate({ scopes: none, charges }).admitsCandidate(u, c0, s.at, h));
    expect(new ScopeGate({ scopes, charges }).admitsCandidate(u, c1, s.at, h)).toEqual(new ScopeGate({ scopes, charges: oneDraw(h) }).admitsCandidate(u, c1, s.at, h));
  });
});
